// Pen expressiveness index — record JAH-GPC-STYLUSPEN-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"pressure_levels": 4096, "battery_h": 12};
var value = (m.pressure_levels/1000*m.battery_h);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-STYLUSPEN-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-STYLUSPEN-000001|' + value.toFixed(2) + ' expressiveness index');

